import{_ as t,o,c as r,a6 as a}from"./chunks/framework.BJFjZBwW.js";const g=JSON.parse('{"title":"Adding protocols","description":"","frontmatter":{},"headers":[],"relativePath":"participate/adding-protocols.md","filePath":"participate/adding-protocols.md","lastUpdated":1773060450000}'),i={name:"participate/adding-protocols.md"};function l(n,e,s,d,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adding-protocols" tabindex="-1">Adding protocols <a class="header-anchor" href="#adding-protocols" aria-label="Permalink to &quot;Adding protocols&quot;">​</a></h1><p>Adding your device protocol to OpenMQTTGateway increases interoperability and creates new use cases. Use the steps below to pick the right path and upstream your changes.</p><div class="tip custom-block"><p class="custom-block-title">Before you open a PR</p><p>Read the <a href="./development.html">Development contributions guide</a> for naming rules, QA, and PR steps. It keeps your protocol addition reviewable.</p></div><h2 id="rf-or-ir" tabindex="-1">RF or IR <a class="header-anchor" href="#rf-or-ir" aria-label="Permalink to &quot;RF or IR&quot;">​</a></h2><ol><li>Implement or extend the protocol in the upstream libs first: <a href="https://github.com/1technophile/rc-switch" target="_blank" rel="noreferrer">RCSwitch</a> or <a href="https://github.com/pilight/pilight" target="_blank" rel="noreferrer">Pilight</a> for RF, and <a href="https://github.com/crankyoldgit/IRremoteESP8266" target="_blank" rel="noreferrer">IRRemoteESP8266</a> for IR.</li><li>Once merged (or while your PR is pending), wire it in OMG as a new decoder/mapping.</li><li>Add a short test sniff/build locally with the relevant environment (for example <code>esp32dev-all-test</code>).</li></ol><h2 id="ble" tabindex="-1">BLE <a class="header-anchor" href="#ble" aria-label="Permalink to &quot;BLE&quot;">​</a></h2><ol><li>For BLE message decoding, OpenMQTTGateway uses <a href="https://decoder.theengs.io/" target="_blank" rel="noreferrer">Theengs Decoder</a>. Submit new device decoders directly to the <a href="https://github.com/theengs/decoder" target="_blank" rel="noreferrer">GitHub repository</a>.</li><li>After the decoder exists, ensure the device is reported correctly through OMG (advertising devices are supported without connection).</li><li>Build locally for a BLE-enabled environment and validate the payload.</li></ol><p>Notes:</p><ul><li>We support reading <strong>advertising</strong> BLE devices (they broadcast regularly without a connection).</li><li>Keep payloads compact and follow existing JSON fields for consistency.</li></ul>',9)])])}const u=t(i,[["render",l]]);export{g as __pageData,u as default};
